import subprocess, sys, base64
from pathlib import Path
FILES={'tools/py/web_mobile_shortlist.py':b'',
       'tools/ps1/run_web_mobile_shortlist.ps1':b'',
       'tests/smoke/test_web_mobile_shortlist.py':b''}
def run(a,cwd=None,check=True): subprocess.run(a,cwd=cwd,check=check)
def root(here):
    p=here
    for _ in range(8):
        if (p/'.git').exists(): return p
        p=p.parent
    return here
def main():
    here=Path(__file__).resolve(); r=root(here)
    for rel,b in FILES.items():
        p=r/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(b))
    try: run(['git','checkout','-B','step/PA-341-web-mobile-shortlist'], r)
    except Exception: pass
    try: run(['git','add','-A'], r)
    except Exception: pass
    try: run(['git','commit','-m','PA-341: add web/mobile shortlist generator + runner + smoke'], r, check=False)
    except Exception: pass
    try: run(['git','push','-u','origin','step/PA-341-web-mobile-shortlist'], r, check=False)
    except Exception: pass
    print('PA-341 done.')
if __name__=='__main__': main()
